INSERT INTO dbo.tender_answer (answerId, category, question, keywords, answerText, evidence, owner, status, reviewDate) VALUES (N'hosting-backup', N'Resilience', N'Where is your data hosted and how is it backed up?', N'["hosted", "hosting", "data centre", "data center", "cloud", "backup", "backed up", "stored", "storage", "residency"]', N'CLG''s core systems run on Microsoft 365 and Microsoft Azure; CLG''s own Azure services are hosted in the UK South region. [confirm: Microsoft 365 data residency, backup approach and retention period.]', N'[]', N'IT Security', N'Draft', NULL);
